'use strict'

const { parallel, series, watch } = require('gulp')
const createTask = require('./gulp.d/lib/create-task')
const exportTasks = require('./gulp.d/lib/export-tasks')
const log = require('fancy-log')

const bundleName = 'ui'
const buildDir = 'build'
const previewSrcDir = 'preview-src'
const previewDestDir = 'public'
const srcDir = 'src'
const destDir = `${previewDestDir}/_`
// The bundle is named for the version of this package, which `just bump` moves
// in lockstep with the rest of the workspace.
const { version } = require('./package.json')
const { reload: livereload } = process.env.LIVERELOAD === 'true' ? require('gulp-connect') : {}
const serverConfig = { host: '0.0.0.0', port: 5252, livereload }

const task = require('./gulp.d/tasks')
const glob = {
  all: [srcDir, previewSrcDir],
}

// NOTE linting and formatting are Nx targets (`nx run ui-bundle:lint`), not gulp
// tasks. The gulp plugin wrappers for eslint and stylelint are ESM-only, which
// this CommonJS pipeline cannot require, and Nx caches the standalone binaries.

const cleanTask = createTask({
  name: 'clean',
  desc: 'Clean files and folders generated by build',
  call: task.remove(['build', 'public', '.tsbuild']),
})

const buildTask = createTask({
  name: 'build',
  desc: 'Build and stage the UI assets for bundling',
  call: task.build(
    srcDir,
    destDir,
    process.argv.slice(2).some((name) => name.startsWith('preview'))
  ),
})

const bundleBuildTask = createTask({
  name: 'bundle:build',
  call: series(cleanTask, buildTask),
})

const bundlePackTask = createTask({
  name: 'bundle:pack',
  desc: 'Create a bundle of the staged UI assets for publishing',
  call: task.pack(destDir, buildDir, bundleName, version),
})

const bundleAliasTask = createTask({
  name: 'bundle:alias',
  desc: 'Copy the versioned bundle to a stable, unversioned name',
  call: task.alias(buildDir, bundleName, version, (versioned, stable) => {
    if (process.env.CI) return
    log(`Bundle: ${versioned}`)
    log(`Antora option: --ui-bundle-url=${stable}`)
  }),
})

const bundleTask = createTask({
  name: 'bundle',
  desc: 'Clean, build, and bundle the UI for publishing',
  call: series(bundleBuildTask, bundlePackTask, bundleAliasTask),
})

const buildPreviewPagesTask = createTask({
  name: 'preview:build-pages',
  call: task.buildPreviewPages(srcDir, previewSrcDir, previewDestDir, livereload),
})

const previewBuildTask = createTask({
  name: 'preview:build',
  desc: 'Process and stage the UI assets and generate pages for the preview',
  call: parallel(buildTask, buildPreviewPagesTask),
})

const previewServeTask = createTask({
  name: 'preview:serve',
  call: task.serve(previewDestDir, serverConfig, () => watch(glob.all, previewBuildTask)),
})

const previewTask = createTask({
  name: 'preview',
  desc: 'Generate a preview site and launch a server to view it',
  call: series(previewBuildTask, previewServeTask),
})

module.exports = exportTasks(
  bundleTask,
  cleanTask,
  buildTask,
  bundleTask,
  bundlePackTask,
  bundleAliasTask,
  previewTask,
  previewBuildTask
)
